import { patchHtml } from '../phone-v2/dom-patch.mjs';
import { locationServices } from './location-service-model.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountLocationServicesBar(container,{notes,getContext,openAppServices,openDetective,openPartTime=()=>{},onLocationChanged=()=>{}}){
 const doc=container.ownerDocument,win=doc.defaultView,root=doc.createElement('section');root.className='location-service-row';root.setAttribute('aria-label','当前地点备注与服务');container.prepend(root);const style=doc.createElement('style');style.textContent=`.location-service-row{position:relative;display:flex;align-items:center;gap:8px;width:100%;padding:2px 0 5px;pointer-events:auto;flex:none;font:13px -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;color:#dedbe4}.location-service-row *{box-sizing:border-box}.location-service-row label{display:flex;align-items:center;gap:10px;flex:1;min-width:0;border:1px solid #e2deec29;border-radius:11px;background:#ffffff08;padding:0 12px;height:38px}.location-service-row label span{color:#a6a3af;font-size:12px;max-width:160px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:none}.location-service-row input{flex:1;min-width:0;width:100%;height:36px;border:0;outline:0;background:transparent;color:#f0edf5;font:inherit;font-size:13px;padding:0}.location-service-row input::placeholder{color:#938f9d}.location-service-row input:disabled{opacity:.5}.location-service-row button{border:1px solid #ffffff28;border-radius:11px;background:#f5f5f9;color:#1c1c1e;min-height:38px;flex:none;padding:7px 14px;font:500 13px -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;cursor:pointer}.location-service-row button:disabled{opacity:.35;cursor:default}.location-service-row button[data-location-service=app-services]{background:#edf3ff;color:#007aff}.location-service-row .location-note-status[data-error=true]{position:relative;width:auto;max-width:260px;height:auto;clip-path:none;color:#ffb6be;font-size:12px;line-height:1.4}.location-service-row .location-note-status{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:700px){.location-service-row{gap:5px;flex-wrap:wrap}.location-service-row label{height:36px;padding:0 8px;gap:7px;flex-basis:calc(100% - 48px)}.location-service-row label span{max-width:77px;font-size:10px}.location-service-row input{font-size:12px}.location-service-row button{padding:6px 9px;font-size:11px;min-height:36px}}`;root.prepend(style);const body=doc.createElement('div');body.style.cssText='display:contents';root.append(body);
 let destroyed=false,current=null,key='',timer=0,notice='',hasError=false;
 function refresh(){if(destroyed)return;const next=getContext(),nextKey=JSON.stringify([next.date,next.index,next.location?.id]),placeChanged=current&&current.location?.id!==next.location?.id;current=structuredClone(next);if(placeChanged)onLocationChanged(next);const services=locationServices(next.location),text=notes.textFor(next);patchHtml(body,`<label><span title="${esc(next.location?.name??'当前位置')}">${esc(next.location?.name??'当前位置')}</span><input data-location-note aria-label="当前地点备注" placeholder="在这里想做什么…" maxlength="1800" ${next.writable?'':'disabled'}></label><button data-location-note-confirm ${next.writable&&notes.hasPending(next)?'':'disabled'}>确认</button>${services.map(service=>`<button data-location-service="${service}" ${next.writable&&next.serviceWritable!==false?'':'disabled'}>${service==='app-services'?'应用服务':service==='scout'?'物色':service==='part-time'?'打工':'侦探服务'}</button>`).join('')}<span class="location-note-status" data-error="${hasError}" role="status">${esc(notice)}</span>`);const input=root.querySelector('input');if(key!==nextKey||doc.activeElement!==input)input.value=text;key=nextKey;}
 async function flush(){win.clearTimeout(timer);await notes.flush();refresh();}
 async function confirm(){win.clearTimeout(timer);try{await notes.confirm(getContext());notice='地点备注已加入日程';hasError=false;}catch(error){notice=error.message;hasError=true;refresh();throw error;}refresh();}
 function input(event){if(!event.target.hasAttribute('data-location-note'))return;try{notes.setText(event.target.value,{context:current});notice='';hasError=false;win.clearTimeout(timer);timer=win.setTimeout(()=>{void flush().catch(error=>{notice=error.message;hasError=true;refresh();});},250);refresh();}catch(error){notice=error.message;refresh();}}
 function click(event){const button=event.target.closest('button');if(!button||button.disabled)return;if(button.hasAttribute('data-location-note-confirm')){void confirm().catch(()=>{});return;}if(!button.hasAttribute('data-location-service'))return;const latest=getContext();if(!latest.writable||latest.serviceWritable===false||!locationServices(latest.location).includes(button.dataset.locationService))return;void flush().then(()=>button.dataset.locationService==='app-services'?openAppServices():button.dataset.locationService==='part-time'?openPartTime():openDetective(button.dataset.locationService)).catch(error=>{notice=error.message;hasError=true;refresh();});}
 function keydown(event){if(event.key==='Enter'&&!event.isComposing&&event.keyCode!==229&&event.target.hasAttribute('data-location-note')){event.preventDefault();void confirm().catch(()=>{});}}
 root.addEventListener('input',input);root.addEventListener('click',click);root.addEventListener('keydown',keydown);refresh();
 return {root,refresh,flush,destroy(){destroyed=true;win.clearTimeout(timer);root.removeEventListener('input',input);root.removeEventListener('click',click);root.removeEventListener('keydown',keydown);root.remove();}};
}
